CREATE TABLE IF NOT EXISTS public.tenant_domains (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE, host text NOT NULL, kind text NOT NULL CHECK (kind IN ('subdomain','custom')), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','active')), notes text, requested_by uuid, approved_by uuid, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS tenant_domains_host_unique ON public.tenant_domains (lower(host)); ALTER TABLE public.tenant_domains ENABLE ROW LEVEL SECURITY;